from pathlib import Path
import json,time
base=Path.home()/".local/share/prediction-project-executor/campaigns/FULL-A2Z-LIVE-20261004-V4"
task="A2Z-V4-ASTRA-PREBUILD-DIRECT-20261007-R4P2"
result=base/"model_results"/(task+".json")
state=base/"models/STATE.json"
cont=base/"models/CONTINUATION.json"
deadline=time.time()+120
while time.time()<deadline:
    if result.is_file():
        o=json.loads(result.read_text(encoding="utf-8"))
        f=o.get("final")
        r=json.loads(f) if isinstance(f,str) else f
        d=(r or {}).get("decision")
        if d=="APPROVE": raise SystemExit(0)
        if d=="REVISE": raise SystemExit(11)
        if d=="REJECT": raise SystemExit(12)
        raise SystemExit(29)
    time.sleep(2)
for p in (cont,state):
    if p.is_file():
        try:
            o=json.loads(p.read_text(encoding="utf-8"))
        except Exception:
            continue
        if o.get("task_id")==task:
            s=o.get("state")
            if s=="PAUSED_USAGE_LIMIT": raise SystemExit(30)
            if s in {"FAILED","ERROR","BLOCKED"}: raise SystemExit(31)
raise SystemExit(32)
